import { TEAMS } from './nfl-teams'
const TEAM_COLOR = Object.fromEntries(TEAMS.map(t => [t.short, { color: t.color, color2: t.color2 }]))

// Defensive linemen (EDGE, DT): the current-player pool for DL mode. Career also uses it for real trade targets (a pass rusher at the deadline).
// Ratings are on the 0-11 grade scale (F … S); null = not rated yet.
// pos: EDGE or DT (ESPN's listed position; a listed DE at 285+ lb plays inside, so DT); subpos: the same, lower case; years: their stretch with the team.
// Height (total inches), weight (lbs) and jersey number from ESPN's rosters (Nov 2026).
// skin: #f0c4a0 white  #b07848 mixed/Polynesian/Latino  #5e3c22 Black  #3a2010 very dark Black
export const DL_TYPES = ['getOff', 'speed', 'size', 'powerMoves', 'finesseMoves', 'strength', 'playRecognition', 'bend', 'blockShed']
export const DL_LITE_TYPES = ['getOff', 'powerMoves', 'finesseMoves', 'size']

export const DL_CATEGORIES = [
  { id: 'physical', label: 'Physical', types: ['getOff', 'speed', 'size', 'strength', 'bend'] },
  { id: 'skill',    label: 'Skill',    types: ['powerMoves', 'finesseMoves', 'blockShed', 'playRecognition'] },
]

export const DL_ATTR = {
  getOff:          { label: 'Get Off',          shortLabel: 'GET', category: 'physical', col: 'var(--c-arm)',  hex: '#f87171', bodyZone: 'legs' },
  speed:           { label: 'Speed',            shortLabel: 'SPD', category: 'physical', col: 'var(--c-mob)',  hex: '#60a5fa', bodyZone: 'legs' },
  size:            { label: 'Size',             shortLabel: 'SZE', category: 'physical', col: 'var(--c-vis)',  hex: '#38bdf8', bodyZone: 'core' },
  strength:        { label: 'Strength',         shortLabel: 'STR', category: 'physical', col: 'var(--c-comp)', hex: '#fbbf24', bodyZone: 'core' },
  bend:            { label: 'Bend',             shortLabel: 'BND', category: 'physical', col: 'var(--c-lead)', hex: '#a78bfa', bodyZone: 'core' },
  powerMoves:      { label: 'Power Moves',      shortLabel: 'PWR', category: 'skill',    col: 'var(--c-str)',  hex: '#fb923c', bodyZone: 'arm'  },
  finesseMoves:    { label: 'Finesse Moves',    shortLabel: 'FIN', category: 'skill',    col: 'var(--c-acc)',  hex: '#34d399', bodyZone: 'hand' },
  blockShed:       { label: 'Block Shed',       shortLabel: 'SHD', category: 'skill',    col: 'var(--c-pkt)',  hex: '#2dd4bf', bodyZone: 'arm'  },
  playRecognition: { label: 'Play Recognition', shortLabel: 'REC', category: 'skill',   col: 'var(--c-iq)',   hex: '#e879f9', bodyZone: 'head' },
}
// Size, the 9th rating: worked out from the bio, 85% weight, 15% height, against his own spot, so the average
// man at the spot is a B. An edge is measured against edges (233 lb = F, 280 lb = S) and a tackle against tackles
// (257 lb = F, 345 lb = S). The Size chip's man decides which spot the build plays
export const DL_SIZE_SCALE = { edge: { lb: [233, 280], in: [73, 78] }, dt: { lb: [257, 345], in: [72, 78] } }
export const dlSizeGrade = (height, weight, spot = 'edge') => {
  const g = (v, [lo, hi]) => Math.max(0, Math.min(11, (v - lo) / (hi - lo) * 11))
  const s = DL_SIZE_SCALE[spot === 'dt' ? 'dt' : 'edge']
  return Math.round(g(weight, s.lb) * 0.85 + g(height, s.in) * 0.15)
}
// how much of a pass rusher he is: get-off, bend, the moves, the speed
export const passRush = p => { const a = p.attrs; return ((a.getOff ?? 5) * 1.2 + (a.bend ?? 5) + (a.finesseMoves ?? 5) + (a.powerMoves ?? 5) * 0.8 + (a.speed ?? 5) * 0.8) / 4.8 }

